CREATE OR REPLACE FUNCTION public.assert_cart_support_intent_consistency()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  item_id uuid := COALESCE(
    (to_jsonb(NEW) ->> 'cart_item_id')::uuid,
    (to_jsonb(OLD) ->> 'cart_item_id')::uuid,
    (to_jsonb(NEW) ->> 'id')::uuid,
    (to_jsonb(OLD) ->> 'id')::uuid
  );
  item_mode text;
  item_has_message boolean;
  intent_mode text;
  intent_has_message boolean;
  is_eligible boolean;
  intent_privacy_state text;
BEGIN
  SELECT display_mode, has_fan_message INTO item_mode, item_has_message
    FROM cart_items WHERE id = item_id;
  SELECT display_mode, fan_message_ciphertext IS NOT NULL, privacy_state
    INTO intent_mode, intent_has_message, intent_privacy_state
    FROM support_intents WHERE cart_item_id = item_id;
  SELECT EXISTS (
    SELECT 1
    FROM cart_items ci
    JOIN support_intents si ON si.cart_item_id = ci.id
    JOIN gift_variant_idol_eligibility eligibility
      ON eligibility.gift_variant_id = ci.gift_variant_id
     AND eligibility.idol_id = si.idol_id
    WHERE ci.id = item_id
  ) INTO is_eligible;

  IF item_mode IS NULL OR intent_mode IS NULL
     OR item_mode <> intent_mode
     OR (intent_privacy_state <> 'PURGED' AND item_has_message <> intent_has_message)
     OR NOT is_eligible THEN
    RAISE EXCEPTION 'cart item and support intent privacy projection diverge'
      USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.assert_checkout_quote_consistency()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  session_id uuid := COALESCE(
    (to_jsonb(NEW) ->> 'checkout_session_id')::uuid,
    (to_jsonb(OLD) ->> 'checkout_session_id')::uuid,
    (to_jsonb(NEW) ->> 'id')::uuid,
    (to_jsonb(OLD) ->> 'id')::uuid
  );
  session_row checkout_sessions%ROWTYPE;
  line_count bigint;
  invalid_count bigint;
  line_subtotal numeric;
  line_tax numeric;
  line_discount numeric;
  line_total numeric;
BEGIN
  SELECT * INTO session_row FROM checkout_sessions WHERE id = session_id;
  IF session_row.id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT count(*),
         count(*) FILTER (WHERE
           q.checkout_quote_id <> session_row.quote_id
           OR ci.cart_id <> session_row.cart_id
           OR ci.gift_variant_id <> q.gift_variant_id
           OR ci.quantity <> q.quantity
           OR p.market <> session_row.market
           OR p.currency <> session_row.currency
           OR p.amount_minor <> q.unit_amount_minor
         ),
         COALESCE(sum(q.line_subtotal_minor), 0),
         COALESCE(sum(q.tax_amount_minor), 0),
         COALESCE(sum(q.discount_amount_minor), 0),
         COALESCE(sum(q.line_total_minor), 0)
    INTO line_count, invalid_count, line_subtotal, line_tax, line_discount, line_total
    FROM checkout_quote_lines q
    JOIN cart_items ci ON ci.id = q.cart_item_id
    JOIN prices p ON p.id = q.price_id
    WHERE q.checkout_session_id = session_id;

  IF line_count = 0 OR invalid_count <> 0
     OR line_subtotal <> session_row.subtotal_minor
     OR line_tax <> session_row.tax_amount_minor
     OR line_discount <> session_row.discount_amount_minor
     OR line_total + session_row.shipping_amount_minor + session_row.fee_amount_minor
        <> session_row.total_amount_minor THEN
    RAISE EXCEPTION 'checkout quote lines do not match the immutable session snapshot'
      USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.assert_fulfillment_aggregate()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  target_order_id uuid;
  current_order orders%ROWTYPE;
  total_count bigint;
  delivered_count bigint;
  canceled_count bigint;
  hold_count bigint;
  progressing_count bigint;
  derived_status text;
  invalid_active_count bigint;
BEGIN
  target_order_id := COALESCE(
    (to_jsonb(NEW) ->> 'order_id')::uuid,
    (to_jsonb(OLD) ->> 'order_id')::uuid,
    (to_jsonb(NEW) ->> 'id')::uuid,
    (to_jsonb(OLD) ->> 'id')::uuid
  );
  SELECT * INTO current_order FROM orders WHERE id = target_order_id;
  IF current_order.id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT count(*),
         count(*) FILTER (WHERE status = 'DELIVERED'),
         count(*) FILTER (WHERE status = 'CANCELED'),
         count(*) FILTER (WHERE status = 'ON_HOLD'),
         count(*) FILTER (WHERE status IN ('PREPARING', 'DELIVERED')),
         count(*) FILTER (
           WHERE status IN ('PREPARING', 'DELIVERED', 'ON_HOLD')
             AND NOT (
               current_order.order_status IN ('OPEN', 'CLOSED')
               AND current_order.payment_status IN ('PAID', 'PARTIALLY_REFUNDED', 'REFUNDED')
             )
         )
  INTO total_count, delivered_count, canceled_count, hold_count,
       progressing_count, invalid_active_count
  FROM fulfillments
  WHERE order_id = target_order_id;

  IF total_count = 0 OR invalid_active_count <> 0 THEN
    RAISE EXCEPTION 'fulfillment aggregate requires paid active work and at least one row'
      USING ERRCODE = '23514';
  END IF;

  derived_status := CASE
    WHEN canceled_count = total_count THEN 'CANCELED'
    WHEN delivered_count = total_count THEN 'DELIVERED'
    WHEN hold_count > 0 THEN 'ON_HOLD'
    WHEN progressing_count > 0 THEN 'PREPARING'
    ELSE 'PENDING'
  END;

  IF current_order.fulfillment_status <> derived_status THEN
    RAISE EXCEPTION 'order fulfillment aggregate does not match fulfillment rows'
      USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.assert_fulfillment_event_head()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  target_fulfillment_id uuid;
  current_fulfillment fulfillments%ROWTYPE;
  head_event fulfillment_events%ROWTYPE;
BEGIN
  target_fulfillment_id := COALESCE(
    (to_jsonb(NEW) ->> 'fulfillment_id')::uuid,
    (to_jsonb(OLD) ->> 'fulfillment_id')::uuid,
    (to_jsonb(NEW) ->> 'id')::uuid,
    (to_jsonb(OLD) ->> 'id')::uuid
  );

  SELECT * INTO current_fulfillment FROM fulfillments WHERE id = target_fulfillment_id;
  IF current_fulfillment.id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT * INTO head_event
  FROM fulfillment_events
  WHERE fulfillment_id = target_fulfillment_id
  ORDER BY sequence DESC
  LIMIT 1;

  IF head_event.id IS NULL
     OR head_event.sequence <> current_fulfillment.version
     OR head_event.to_status <> current_fulfillment.status
     OR (current_fulfillment.status IN ('ON_HOLD', 'CANCELED')
       AND head_event.reason_code <> current_fulfillment.hold_reason_code) THEN
    RAISE EXCEPTION 'fulfillment event head must equal versioned fulfillment state'
      USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.assert_inventory_consistency()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  target_item uuid;
  target_location uuid;
  balance_on_hand bigint;
  balance_reserved bigint;
  balance_version bigint;
  ledger_on_hand numeric;
  ledger_reserved numeric;
  ledger_count bigint;
  first_version bigint;
  last_version bigint;
  active_reserved numeric;
BEGIN
  target_item := COALESCE(
    (to_jsonb(NEW) ->> 'inventory_item_id')::uuid,
    (to_jsonb(OLD) ->> 'inventory_item_id')::uuid
  );
  target_location := COALESCE(
    (to_jsonb(NEW) ->> 'location_id')::uuid,
    (to_jsonb(OLD) ->> 'location_id')::uuid
  );

  SELECT on_hand, reserved, version INTO balance_on_hand, balance_reserved, balance_version
    FROM inventory_balances
    WHERE inventory_item_id = target_item AND location_id = target_location
    FOR UPDATE;

  IF balance_on_hand IS NULL THEN
    RAISE EXCEPTION 'inventory balance is missing' USING ERRCODE = '23514';
  END IF;

  SELECT COALESCE(sum(delta_on_hand), 0), COALESCE(sum(delta_reserved), 0),
         count(*), min(balance_version_before), max(balance_version_after)
    INTO ledger_on_hand, ledger_reserved, ledger_count, first_version, last_version
    FROM inventory_ledger
    WHERE inventory_item_id = target_item AND location_id = target_location;

  SELECT COALESCE(sum(quantity), 0) INTO active_reserved
    FROM inventory_reservations
    WHERE inventory_item_id = target_item AND location_id = target_location
      AND status = 'ACTIVE';

  IF ledger_on_hand <> balance_on_hand
     OR ledger_reserved <> balance_reserved
     OR ledger_count <> balance_version
     OR first_version IS DISTINCT FROM 0
     OR last_version IS DISTINCT FROM balance_version
     OR active_reserved <> balance_reserved THEN
    RAISE EXCEPTION 'inventory balance, ledger, and active reservations diverge'
      USING ERRCODE = '23514';
  END IF;

  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.assert_inventory_item_variant_consistency()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  target_variant_id uuid;
  variant_sku text;
  variant_policy text;
  item_sku text;
  item_policy text;
BEGIN
  target_variant_id := COALESCE(
    (to_jsonb(NEW) ->> 'gift_variant_id')::uuid,
    (to_jsonb(OLD) ->> 'gift_variant_id')::uuid,
    (to_jsonb(NEW) ->> 'id')::uuid,
    (to_jsonb(OLD) ->> 'id')::uuid
  );
  SELECT sku, inventory_policy INTO variant_sku, variant_policy
    FROM gift_variants WHERE id = target_variant_id;
  SELECT sku, policy INTO item_sku, item_policy
    FROM inventory_items WHERE gift_variant_id = target_variant_id;
  IF item_sku IS NOT NULL AND (item_sku <> variant_sku OR item_policy <> variant_policy) THEN
    RAISE EXCEPTION 'inventory item sku/policy must match its gift variant'
      USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.assert_notification_attempt_consistency()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  target_delivery_id uuid;
  delivery notification_deliveries%ROWTYPE;
  actual_count bigint;
  latest_outcome text;
BEGIN
  target_delivery_id := COALESCE(
    (to_jsonb(NEW) ->> 'notification_delivery_id')::uuid,
    (to_jsonb(OLD) ->> 'notification_delivery_id')::uuid,
    (to_jsonb(NEW) ->> 'id')::uuid,
    (to_jsonb(OLD) ->> 'id')::uuid
  );

  SELECT * INTO delivery FROM notification_deliveries WHERE id = target_delivery_id;
  IF delivery.id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT count(*) INTO actual_count
  FROM notification_delivery_attempts
  WHERE notification_delivery_id = target_delivery_id;
  SELECT outcome INTO latest_outcome
  FROM notification_delivery_attempts
  WHERE notification_delivery_id = target_delivery_id
  ORDER BY sequence DESC
  LIMIT 1;

  IF actual_count <> delivery.attempt_count
     OR (delivery.status = 'SENT' AND latest_outcome IS DISTINCT FROM 'SUCCEEDED')
     OR (delivery.status IN ('RETRY_SCHEDULED', 'FAILED')
       AND latest_outcome NOT IN ('FAILED', 'UNKNOWN')) THEN
    RAISE EXCEPTION 'notification delivery and append-only attempts diverge'
      USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.assert_order_aggregate()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  target_order_id uuid;
  current_order orders%ROWTYPE;
  item_count bigint;
  fulfillment_count bigint;
  policy_count bigint;
  quote_line_count bigint;
  item_subtotal numeric;
  item_tax numeric;
  item_discount numeric;
  item_total numeric;
  foreign_currency_count bigint;
BEGIN
  target_order_id := COALESCE(
    (to_jsonb(NEW) ->> 'order_id')::uuid,
    (to_jsonb(OLD) ->> 'order_id')::uuid,
    (to_jsonb(NEW) ->> 'id')::uuid,
    (to_jsonb(OLD) ->> 'id')::uuid
  );

  SELECT * INTO current_order FROM orders WHERE id = target_order_id FOR UPDATE;
  IF current_order.id IS NULL THEN
    RETURN NULL;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM checkout_sessions session
    WHERE session.id = current_order.checkout_session_id
      AND session.quote_id = current_order.checkout_quote_id
      AND session.cart_id = current_order.cart_id
      AND session.market = current_order.market
      AND session.currency = current_order.currency
      AND session.quote_revision = current_order.quote_revision
      AND session.quote_expires_at = current_order.quote_expires_at
      AND session.subtotal_minor = current_order.subtotal_minor
      AND session.tax_amount_minor = current_order.tax_amount_minor
      AND session.shipping_amount_minor = current_order.shipping_amount_minor
      AND session.fee_amount_minor = current_order.fee_amount_minor
      AND session.discount_amount_minor = current_order.discount_amount_minor
      AND session.total_amount_minor = current_order.total_amount_minor
  ) THEN
    RAISE EXCEPTION 'order amount snapshot must reproduce its checkout session'
      USING ERRCODE = '23514';
  END IF;

  SELECT count(*), COALESCE(sum(line_subtotal_minor), 0), COALESCE(sum(tax_amount_minor), 0),
         COALESCE(sum(discount_amount_minor), 0), COALESCE(sum(line_total_minor), 0),
         count(*) FILTER (WHERE currency <> current_order.currency)
  INTO item_count, item_subtotal, item_tax, item_discount, item_total, foreign_currency_count
  FROM order_items
  WHERE order_id = target_order_id;

  SELECT count(*) INTO policy_count FROM policy_acceptances WHERE order_id = target_order_id;
  SELECT count(*) INTO fulfillment_count FROM fulfillments WHERE order_id = target_order_id;
  SELECT count(*) INTO quote_line_count
  FROM checkout_quote_lines
  WHERE checkout_session_id = current_order.checkout_session_id
    AND checkout_quote_id = current_order.checkout_quote_id;

  IF item_count = 0 OR item_count <> quote_line_count
     OR policy_count = 0 OR fulfillment_count <> item_count
     OR foreign_currency_count <> 0
     OR item_subtotal <> current_order.subtotal_minor
     OR item_tax <> current_order.tax_amount_minor
     OR item_discount <> current_order.discount_amount_minor
     OR item_total + current_order.shipping_amount_minor + current_order.fee_amount_minor
        <> current_order.total_amount_minor THEN
    RAISE EXCEPTION 'order lines, policies, fulfillments, and amount snapshot diverge'
      USING ERRCODE = '23514';
  END IF;

  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.assert_order_event_head()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  target_order_id uuid;
  current_order orders%ROWTYPE;
  head_event order_events%ROWTYPE;
BEGIN
  target_order_id := COALESCE(
    (to_jsonb(NEW) ->> 'order_id')::uuid,
    (to_jsonb(OLD) ->> 'order_id')::uuid,
    (to_jsonb(NEW) ->> 'id')::uuid,
    (to_jsonb(OLD) ->> 'id')::uuid
  );

  SELECT * INTO current_order FROM orders WHERE id = target_order_id;
  IF current_order.id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT * INTO head_event
  FROM order_events
  WHERE order_id = target_order_id
  ORDER BY sequence DESC
  LIMIT 1;

  IF head_event.id IS NULL
     OR head_event.sequence <> current_order.version
     OR head_event.to_order_status <> current_order.order_status
     OR head_event.to_payment_status <> current_order.payment_status
     OR head_event.to_dispute_status <> current_order.dispute_status
     OR head_event.to_fulfillment_status <> current_order.fulfillment_status
     OR head_event.to_payment_attempt_id IS DISTINCT FROM current_order.current_payment_attempt_id THEN
    RAISE EXCEPTION 'order event head must equal the versioned order aggregate'
      USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.assert_payment_config_publication_outbox()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  config_version_number positive_version;
  event_count integer;
BEGIN
  SELECT version INTO config_version_number FROM config_versions WHERE id = NEW.config_version_id;
  SELECT count(*) INTO event_count FROM outbox_events
    WHERE event_type = 'PAYMENT_CONFIG_PUBLISHED'
      AND aggregate_type = 'PAYMENT_CONFIG'
      AND aggregate_id = NEW.config_version_id
      AND aggregate_version = config_version_number
      AND primary_subject_id = NEW.id;
  IF event_count <> 1 THEN
    RAISE EXCEPTION 'payment config publication and outbox record must commit together'
      USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.assert_payment_provider_health_head()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  account_id uuid := COALESCE(
    (to_jsonb(NEW) ->> 'provider_account_id')::uuid,
    (to_jsonb(NEW) ->> 'id')::uuid
  );
  matching_count integer;
BEGIN
  SELECT count(*) INTO matching_count
    FROM public.payment_provider_accounts account
    JOIN public.payment_provider_health_events event
      ON event.provider_account_id = account.id
      AND event.sequence = account.version
      AND event.to_status = account.health_status
    WHERE account.id = account_id;
  IF matching_count <> 1 THEN
    RAISE EXCEPTION 'payment provider health and append-only evidence diverge'
      USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.assert_payment_provider_translation_package(target_provider_config_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  english_hash sha256_hex;
  translation_count integer;
  approved_count integer;
  lineage_count integer;
BEGIN
  SELECT source_hash INTO english_hash
    FROM payment_provider_config_translations
    WHERE provider_config_id = target_provider_config_id AND locale = 'en';

  IF english_hash IS NULL THEN
    RAISE EXCEPTION 'payment provider config publication requires an English translation'
      USING ERRCODE = '23514';
  END IF;

  SELECT count(*),
    count(*) FILTER (WHERE latest.status = 'APPROVED'),
    count(*) FILTER (WHERE translation.translated_from_source_hash = english_hash)
    INTO translation_count, approved_count, lineage_count
    FROM payment_provider_config_translations translation
    LEFT JOIN LATERAL (
      SELECT review.status
      FROM payment_provider_config_translation_reviews review
      WHERE review.provider_config_translation_id = translation.id
      ORDER BY review.sequence DESC
      LIMIT 1
    ) latest ON true
    WHERE translation.provider_config_id = target_provider_config_id;

  IF translation_count <> 7 OR approved_count <> 7 OR lineage_count <> 7 THEN
    RAISE EXCEPTION 'payment provider config publication requires seven approved current translations'
      USING ERRCODE = '23514';
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.assert_price_book_publication()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  price_count integer;
  published_count integer;
BEGIN
  IF NEW.lifecycle = 'PUBLISHED' THEN
    SELECT count(*), count(*) FILTER (WHERE status = 'PUBLISHED')
      INTO price_count, published_count
      FROM prices WHERE price_book_id = NEW.id AND price_book_revision = NEW.revision;
    IF price_count = 0 OR price_count <> published_count THEN
      RAISE EXCEPTION 'published price-book revision requires a non-empty published price set'
        USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.assert_provider_event_association()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  association_count integer;
BEGIN
  SELECT count(*) INTO association_count
    FROM provider_event_associations WHERE provider_event_id = NEW.id;
  IF association_count NOT IN (1, 2) THEN
    RAISE EXCEPTION 'provider event requires one initial association and at most one later match'
      USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.assert_refund_allocation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  target_refund_id uuid;
  expected_amount minor_amount;
  allocated_amount numeric;
  allocation_count integer;
BEGIN
  target_refund_id := COALESCE(
    (to_jsonb(NEW) ->> 'refund_id')::uuid,
    (to_jsonb(OLD) ->> 'refund_id')::uuid,
    (to_jsonb(NEW) ->> 'id')::uuid,
    (to_jsonb(OLD) ->> 'id')::uuid
  );
  SELECT requested_amount_minor INTO expected_amount FROM refunds WHERE id = target_refund_id;
  IF expected_amount IS NULL THEN
    RETURN NULL;
  END IF;
  SELECT count(*), COALESCE(sum(amount_minor), 0)
    INTO allocation_count, allocated_amount
    FROM refund_items WHERE refund_id = target_refund_id;
  IF allocation_count = 0 OR allocated_amount <> expected_amount THEN
    RAISE EXCEPTION 'refund allocations must be non-empty and sum exactly to requested amount'
      USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.assert_refund_item_capacity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  target_order_item_id uuid := (to_jsonb(NEW) ->> 'order_item_id')::uuid;
  target_refund_id uuid := COALESCE(
    (to_jsonb(NEW) ->> 'refund_id')::uuid,
    (to_jsonb(NEW) ->> 'id')::uuid
  );
  item_row record;
  item_total minor_amount;
  occupied_total numeric;
BEGIN
  FOR item_row IN
    SELECT DISTINCT item.order_item_id
    FROM public.refund_items item
    WHERE (target_order_item_id IS NOT NULL AND item.order_item_id = target_order_item_id)
       OR (target_order_item_id IS NULL AND item.refund_id = target_refund_id)
  LOOP
    SELECT line_total_minor INTO item_total
      FROM public.order_items
      WHERE id = item_row.order_item_id;
    SELECT COALESCE(sum(item.amount_minor), 0) INTO occupied_total
      FROM public.refund_items item
      JOIN public.refunds refund ON refund.id = item.refund_id
      WHERE item.order_item_id = item_row.order_item_id
        AND refund.status <> 'FAILED';
    IF item_total IS NULL OR occupied_total > item_total THEN
      RAISE EXCEPTION 'refund allocation exceeds order-item total'
        USING ERRCODE = '23514';
    END IF;
  END LOOP;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.assert_translation_initial_review()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  review_count integer;
BEGIN
  EXECUTE format(
    'SELECT count(*) FROM %s WHERE %I = $1 AND sequence = 1 AND status = ''DRAFT''',
    TG_ARGV[0]::regclass,
    TG_ARGV[1]
  ) INTO review_count USING NEW.id;
  IF review_count <> 1 THEN
    RAISE EXCEPTION 'translation creation requires one initial DRAFT review event'
      USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.assert_translation_package(translation_table regclass, parent_column text, parent_id uuid, review_table regclass, review_translation_column text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  english_hash sha256_hex;
  translation_count integer;
  approved_count integer;
  lineage_count integer;
BEGIN
  EXECUTE format(
    'SELECT source_hash FROM %s WHERE %I = $1 AND locale = ''en''',
    translation_table,
    parent_column
  ) INTO english_hash USING parent_id;

  IF english_hash IS NULL THEN
    RAISE EXCEPTION 'publication requires an English translation row'
      USING ERRCODE = '23514';
  END IF;

  EXECUTE format(
    'SELECT count(*), '
    'count(*) FILTER (WHERE latest.status = ''APPROVED''), '
    'count(*) FILTER (WHERE t.translated_from_source_hash = $2) '
    'FROM %s t '
    'LEFT JOIN LATERAL ('
    '  SELECT r.status FROM %s r '
    '  WHERE r.%I = t.id ORDER BY r.sequence DESC LIMIT 1'
    ') latest ON true '
    'WHERE t.%I = $1',
    translation_table,
    review_table,
    review_translation_column,
    parent_column
  ) INTO translation_count, approved_count, lineage_count
    USING parent_id, english_hash;

  IF translation_count <> 7 OR approved_count <> 7 OR lineage_count <> 7 THEN
    RAISE EXCEPTION 'publication requires seven approved translations with current English lineage'
      USING ERRCODE = '23514';
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_cart_item_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  parent_status text;
BEGIN
  SELECT status INTO parent_status FROM carts WHERE id = OLD.cart_id FOR SHARE;
  IF parent_status <> 'ACTIVE' THEN
    RAISE EXCEPTION 'cart items are immutable after the cart leaves ACTIVE'
      USING ERRCODE = '55000';
  END IF;
  IF NEW.id <> OLD.id OR NEW.cart_id <> OLD.cart_id OR NEW.created_at <> OLD.created_at
     OR NEW.request_id <> OLD.request_id
     OR NEW.correlation_id <> OLD.correlation_id THEN
    RAISE EXCEPTION 'cart item ownership is immutable' USING ERRCODE = '55000';
  END IF;
  IF NEW.version <> OLD.version + 1 THEN
    RAISE EXCEPTION 'cart item version must increment exactly once' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_cart_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.version <> OLD.version + 1 THEN
    RAISE EXCEPTION 'cart version must increment exactly once' USING ERRCODE = '23514';
