CREATE OR REPLACE FUNCTION public.guard_inventory_reservation_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'ACTIVE' OR NEW.version <> 1 THEN
      RAISE EXCEPTION 'new reservation must start ACTIVE at version 1'
        USING ERRCODE = '23514';
    END IF;
    IF NOT EXISTS (
      SELECT 1
      FROM public.inventory_items item
      JOIN public.gift_variants variant ON variant.id = item.gift_variant_id
      WHERE item.id = NEW.inventory_item_id
        AND item.gift_variant_id = NEW.gift_variant_id
        AND item.policy = 'TRACKED'
        AND variant.inventory_policy = 'TRACKED'
    ) THEN
      RAISE EXCEPTION 'only TRACKED inventory may be reserved'
        USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.version <> OLD.version + 1 THEN
    RAISE EXCEPTION 'reservation version must increment exactly once' USING ERRCODE = '23514';
  END IF;
  IF (to_jsonb(NEW) - 'status' - 'version' - 'updated_at' - 'committed_at' - 'released_at' - 'expired_at' - 'locked_order_id')
     IS DISTINCT FROM
     (to_jsonb(OLD) - 'status' - 'version' - 'updated_at' - 'committed_at' - 'released_at' - 'expired_at' - 'locked_order_id') THEN
    RAISE EXCEPTION 'reservation identity and quantity are immutable' USING ERRCODE = '55000';
  END IF;
  IF NOT (
    NEW.status = OLD.status
    OR (OLD.status = 'ACTIVE' AND NEW.status IN ('COMMITTED', 'RELEASED', 'EXPIRED'))
  ) THEN
    RAISE EXCEPTION 'invalid reservation status transition' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_nonterminal_payment_lock()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  target_order_id uuid;
  releasing_lock boolean;
BEGIN
  IF TG_TABLE_NAME = 'orders' THEN
    target_order_id := OLD.id;
    releasing_lock := OLD.order_status = 'PENDING_PAYMENT' AND NEW.order_status = 'CANCELED';
  ELSIF TG_TABLE_NAME = 'carts' THEN
    target_order_id := OLD.locked_order_id;
    releasing_lock := OLD.status = 'LOCKED' AND NEW.status = 'EXPIRED';
  ELSE
    target_order_id := OLD.locked_order_id;
    releasing_lock := OLD.status = 'ACTIVE' AND NEW.status IN ('RELEASED', 'EXPIRED');
  END IF;

  IF NOT releasing_lock OR target_order_id IS NULL THEN
    RETURN NEW;
  END IF;

  PERFORM 1 FROM orders WHERE id = target_order_id FOR UPDATE;
  IF EXISTS (
    SELECT 1 FROM payment_attempts attempt
    WHERE attempt.order_id = target_order_id
      AND attempt.status IN ('CREATED', 'REQUIRES_ACTION', 'PROCESSING')
  ) THEN
    RAISE EXCEPTION 'nonterminal payment keeps cart and reservation locked'
      USING ERRCODE = '23514';
  END IF;

  IF EXISTS (
    SELECT 1 FROM payment_attempts attempt
    WHERE attempt.order_id = target_order_id
      AND attempt.status = 'UNKNOWN'
  ) THEN
    IF TG_TABLE_NAME = 'inventory_reservations' THEN
      IF NEW.status = 'EXPIRED' THEN
        IF statement_timestamp() < OLD.expires_at THEN
          RAISE EXCEPTION 'UNKNOWN reservation expiry requires its elapsed hold window'
            USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
      END IF;
    END IF;

    RAISE EXCEPTION 'nonterminal payment keeps cart and reservation locked'
      USING ERRCODE = '23514';
  END IF;

  IF TG_TABLE_NAME = 'inventory_reservations' AND EXISTS (
    SELECT 1 FROM payment_attempts attempt
    WHERE attempt.order_id = target_order_id
      AND attempt.status = 'SUCCEEDED'
  ) THEN
    RAISE EXCEPTION 'succeeded payment cannot release or expire reservations'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_notification_delivery_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.version <> 1 OR NEW.status <> 'REQUESTED' OR NEW.attempt_count <> 0 THEN
      RAISE EXCEPTION 'notification delivery must start REQUESTED with zero attempts'
        USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.version <> OLD.version + 1 THEN
    RAISE EXCEPTION 'notification delivery version must increment exactly once'
      USING ERRCODE = '23514';
  END IF;
  IF (to_jsonb(NEW)
        - 'status' - 'attempt_count' - 'next_attempt_at' - 'sent_at'
        - 'last_error_code' - 'version' - 'updated_at')
     IS DISTINCT FROM
     (to_jsonb(OLD)
        - 'status' - 'attempt_count' - 'next_attempt_at' - 'sent_at'
        - 'last_error_code' - 'version' - 'updated_at') THEN
    RAISE EXCEPTION 'notification order, locale, template, and idempotency identity are immutable'
      USING ERRCODE = '55000';
  END IF;
  IF NOT (
    (OLD.status = 'REQUESTED' AND NEW.status IN ('PROCESSING', 'CANCELED'))
    OR (OLD.status = 'PROCESSING' AND NEW.status IN ('SENT', 'RETRY_SCHEDULED', 'FAILED'))
    OR (OLD.status = 'RETRY_SCHEDULED' AND NEW.status IN ('PROCESSING', 'CANCELED', 'FAILED'))
  ) THEN
    RAISE EXCEPTION 'invalid notification delivery transition' USING ERRCODE = '23514';
  END IF;
  IF OLD.status = 'PROCESSING' AND NEW.status IN ('SENT', 'RETRY_SCHEDULED', 'FAILED') THEN
    IF NEW.attempt_count <> OLD.attempt_count + 1 THEN
      RAISE EXCEPTION 'completed notification attempt must increment attempt count once'
        USING ERRCODE = '23514';
    END IF;
  ELSIF NEW.attempt_count <> OLD.attempt_count THEN
    RAISE EXCEPTION 'notification attempt count may change only after processing'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$

